content.content:
1	/* The reader of the Fortress specification. The colours, the type sizes and the Select
2	   button come from the revival page (explorations/coordinator/process-engineering/
3	   revival-story.html); the fonts are the system's, since the reader loads nothing external. */
4	/* The curly quotation marks alone come from a serif face, as in the PDF: in a sans face they look like
5	   straight ticks, and the specification quotes single characters all the time. */
6	@font-face { font-family: "SpecQuotes"; src: local("Times New Roman"), local("TimesNewRomanPSMT"), local("STIX Two Text"), local("Georgia"), local("Nimbus Roman"), local("Liberation Serif"); unicode-range: U+2018-201F; }
7	:root {
8	  --bg: #f6f7f6; --surface: #ffffff; --fg: #1d2421; --muted: #5b6661; --rule: #d8dedb;
9	  --accent: #1f6f5c; --code-bg: #eef1ef; --note-bg: #fbf4e4; --note-rule: #d9b45c;
10	  --rev-bg: #e9f0f8; --rev-rule: #1c548c; --rev-fg: #17446f; --mark: #fff3b8;
11	  --body: "SpecQuotes", "Atkinson Hyperlegible", "Segoe UI", system-ui, -apple-system, sans-serif;
12	  --mono: "JetBrains Mono", ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
13	  --math: "STIX Two Text", "STIXGeneral", "Times New Roman", Times, "Nimbus Roman", serif;
14	}
15	@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
16	  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
17	  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
18	  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark } }
19	:root[data-theme="dark"] {
20	  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
21	  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
22	  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark }
23	
24	* { box-sizing: border-box; }
25	html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
26	body { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55;
27	  margin: 0; padding-inline: max(16px, env(safe-area-inset-left)) max(16px, env(safe-area-inset-right)); padding-block: 0 64px;
28	  overflow-wrap: break-word; }
29	.page { max-width: 46rem; margin: 0 auto; display: flex; flex-direction: column; gap: 24px; padding-top: 20px; }
30	.page > * { min-width: 0; }
31	h1 { font-size: 1.9rem; line-height: 1.2; margin: 0 0 .8rem; text-wrap: balance; }
32	h2 { font-size: 1.35rem; line-height: 1.25; margin: 0 0 .6rem; text-wrap: balance; }
33	h3 { font-size: 1.08rem; margin: 1.3rem 0 .3rem; text-wrap: balance; }
34	h4 { font-size: 1rem; margin: 1.1rem 0 .3rem; }
35	p { margin: 0 0 .8rem; }
36	p, li, dd { max-width: 65ch; }
37	ul, ol { margin: 0 0 .9rem; padding-left: 1.2rem; }
38	li { margin-bottom: .35rem; }
39	li > p:last-child { margin-bottom: 0; }
40	dl { margin: 0 0 .9rem; }
41	dt { font-weight: 700; margin-top: .5em; }
42	dd { margin: .1em 0 0 1.2em; }
43	a { color: var(--accent); }
44	a:focus-visible, button:focus-visible, summary:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
45	/* Code inside a sentence keeps its highlight, with almost no padding at its sides, so that the
46	   quotation marks around it sit close, as in the PDF. Ligatures are off wherever code is shown: the specification's point is
47	   often the ASCII characters themselves, and a ligature would hide them. */
48	code { font-family: var(--mono); font-size: .9em; background: var(--code-bg); padding: .08em .1em; border-radius: 3px; overflow-wrap: anywhere; }
49	code, pre, .tt, .m .kw, .m .op, .m .str, .fx-r { font-variant-ligatures: none; font-feature-settings: "liga" 0, "clig" 0, "calt" 0, "dlig" 0; }
50	code.ul { text-decoration: underline; }
51	strong { font-weight: 700; }
52	blockquote { margin: 0 0 .9rem; padding-left: 1rem; border-left: 3px solid var(--rule); }
53	.center { text-align: center; }
54	.sc { font-variant: small-caps; } .sf { font-family: var(--body); } .rm { font-style: normal; font-family: var(--math); }
55	.it { font-style: italic; } .bf { font-weight: 700; } .tt { font-family: var(--mono); font-size: .9em; }
56	
57	/* the bar */
58	nav.bar { position: sticky; top: 0; z-index: 5; display: flex; gap: 12px; align-items: center; justify-content: space-between;
59	  margin-inline: calc(-1 * max(16px, env(safe-area-inset-left))) calc(-1 * max(16px, env(safe-area-inset-right)));
60	  padding: 8px max(16px, env(safe-area-inset-right)) 8px max(16px, env(safe-area-inset-left));
61	  background: var(--bg); border-bottom: 1px solid var(--rule); font-size: .88rem; }
62	nav.bar a { text-decoration: none; font-weight: 700; white-space: nowrap; padding: 4px 0; }
63	nav.bar .here { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; flex: 1; text-align: center; }
64	nav.bar .count { font-family: var(--mono); font-weight: 600; font-size: .78rem; border: 1px solid var(--rule); border-radius: 999px; padding: 0 .5em; margin-left: .3em; background: var(--surface); }
65	[id] { scroll-margin-top: 56px; }
66	
67	#resume:empty, #chapter-notes:empty, #continue:empty, #storage-warning:empty { display: none; }
68	header.masthead { display: flex; flex-direction: column; gap: .4rem; }
69	header.masthead h1 { margin: 0; }
70	.eyebrow { font-family: var(--mono); font-size: .78rem; color: var(--muted); letter-spacing: .02em; margin: 0; max-width: none; }
71	.standfirst { color: var(--muted); margin: 0 0 .8rem; }
72	.num { font-family: var(--mono); font-size: .78em; font-weight: 400; color: var(--muted); letter-spacing: .02em; }
73	h1 .num { display: block; font-size: .78rem; margin-bottom: .2rem; }
74	
75	nav.parts { border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); padding: 12px 0 4px; margin: 0 0 1rem; }
76	nav.parts { -webkit-user-select: none; user-select: none; }
77	nav.parts h2 { font-size: 1rem; margin: 0 0 .3rem; }
78	nav.parts ol { columns: 2 16rem; margin: 0 0 .5rem; list-style: none; padding: 0; }
79	nav.parts li { break-inside: avoid; }
80	nav.parts a, details.secs a { text-decoration: none; }
81	.nb-tools { text-align: right; margin: -.8rem 0 .3rem; line-height: 1; }
82	
83	details.words { background: var(--surface); border: 1px solid var(--rule); border-radius: 8px; padding: 8px 14px; font-size: .9rem; min-width: 0; }
84	details.words > summary { cursor: pointer; color: var(--muted); line-height: 1.4; padding: 2px 0; }
85	details.words > summary .w-head { font-weight: 700; color: var(--fg); margin-right: .4rem; }
86	details.words[open] > summary { margin-bottom: .4rem; }
87	details.words ul { margin: 0 0 .3rem; }
88	
89	section.part { border-top: 1px solid var(--rule); padding-top: 18px; min-width: 0; }
90	section.sec { min-width: 0; }
91	section.sec > section.sec { border-top: 1px solid var(--rule); padding-top: 18px; margin-top: 22px; }
92	section.sec > section.sec > section.sec { border-top: 0; padding-top: 0; margin-top: 0; }
93	
94	footer.colophon { border-top: 1px solid var(--rule); padding-top: 12px; font-size: .88rem; color: var(--muted); }
95	
96	/* the Select button of the revival page, and the note button beside it */
97	button.sel, .addnote { font-family: var(--mono); font-size: .72rem; font-weight: 600; color: var(--accent); background: var(--surface); border: 1px solid var(--rule); border-radius: 4px; padding: .2em .6em; margin-left: .6rem; vertical-align: .15em; cursor: pointer; -webkit-user-select: none; user-select: none; line-height: 1.4; }
98	button.sel::before { content: "Select"; }
99	.addnote::before { content: "✎"; font-size: .95rem; line-height: 1; }
100	.addnote { border-color: transparent; background: none; color: var(--muted); opacity: .55; padding: .25em .55em; margin-left: .25rem; vertical-align: baseline; }
101	span.addnote { border: 0; padding: .3em .5em; margin-left: 0; white-space: nowrap; }
102	span.addnote:focus-visible { outline: 2px solid var(--accent); }
103	h1 .addnote, h2 .addnote, h3 .addnote, h4 .addnote { opacity: .8; border-color: var(--rule); background: var(--surface); vertical-align: .15em; margin-left: .4rem; }
104	.has-note > .addnote, .has-note > .fx-bar .addnote { color: var(--accent); opacity: 1; }
105	.addnote:hover { opacity: 1; }
106	
107	/* math and code as the specification renders them */
108	.m { font-family: var(--math); font-size: 1.06em; font-style: normal; white-space: nowrap; }
109	.m i { font-style: italic; }
110	.m .kw, .m .op, .m .str, .m .tt { font-family: var(--mono); font-size: .82em; }
111	.m .kw { font-weight: 600; }
112	.m .ty, .m .rm { font-style: normal; }
113	.m .big { font-size: 1.35em; line-height: 1; vertical-align: -.1em; }
114	.m sup, .m sub { font-size: .72em; line-height: 0; }
115	.m .frac { display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: .85em; line-height: 1.15; }
116	.m .frac > span:first-child { border-bottom: 1px solid currentColor; padding: 0 .2em; }
117	.m .frac > span:last-child { padding: 0 .2em; }
118	.m .ovl { border-top: 1px solid currentColor; } .m .unl { border-bottom: 1px solid currentColor; }
119	.m table { display: inline-table; vertical-align: middle; border-collapse: collapse; }
120	.cm { font-family: var(--body); font-size: .88em; color: var(--muted); white-space: nowrap; }
121	p .m, li .m, dd .m, td .m { white-space: normal; }
122	.dm { overflow-x: auto; margin: 0 0 .9rem; padding: 4px 0; text-align: center; }
123	
124	.fx, pre.vb, .tw { position: relative; margin: 0 0 .9rem; }
125	.fx { background: var(--surface); border: 1px solid var(--rule); border-radius: 6px; }
126	.fx-r { overflow-x: auto; padding: 10px 12px; -webkit-overflow-scrolling: touch; }
127	.fx-r .tb { display: inline-block; vertical-align: top; white-space: nowrap; }
128	.fx-r .tb.top { display: block; width: max-content; min-width: 100%; }
129	.fx-r .l { display: block; line-height: 1.6; min-height: .5em; }
130	.fx-r .gapline { display: block; height: .4em; }
131	.fx.tt .fx-r { font-family: var(--mono); font-size: .86rem; }
132	pre { font-family: var(--mono); font-size: .84rem; line-height: 1.5; margin: 0; overflow-x: auto; -webkit-overflow-scrolling: touch; }
133	pre code { background: none; padding: 0; font-size: 1em; overflow-wrap: normal; white-space: pre; }
134	pre.fx-s { padding: 10px 12px; background: var(--code-bg); border-top: 1px solid var(--rule); border-radius: 0 0 5px 5px; }
135	.fx > pre.fx-s:first-child { border-top: 0; border-radius: 5px; }
136	pre.vb { padding: 10px 12px; background: var(--code-bg); border: 1px solid var(--rule); border-radius: 6px; }
137	.fx-bar { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 3px 6px 3px 12px; border-bottom: 1px solid var(--rule); font-family: var(--mono); font-size: .72rem; color: var(--muted); -webkit-user-select: none; user-select: none; }
138	.fx-bar .seg { display: inline-flex; border: 1px solid var(--rule); border-radius: 4px; overflow: hidden; }
139	.fx-bar .seg button { font: inherit; font-weight: 600; color: var(--muted); background: none; border: 0; padding: .25em .7em; cursor: pointer; }
140	.fx-bar .seg button[aria-pressed="true"] { background: var(--code-bg); color: var(--accent); }
141	.fx-bar .seg button.r::before { content: "Rendered"; } .fx-bar .seg button.s::before { content: "Source"; }
142	html[data-code="rendered"] .fx.both > .fx-s, html[data-code="source"] .fx.both > .fx-r { display: none; }
143	html[data-code="source"] .fx.both > .fx-s { border-top: 0; }
144	pre.vb > .addnote, .tw > .addnote, .dm > .addnote { position: absolute; top: 2px; right: 2px; background: var(--surface); border-color: var(--rule); opacity: .9; }
145	.fx > .addnote { position: absolute; top: 2px; right: 2px; background: var(--surface); border-color: var(--rule); opacity: .9; }
146	
147	.tw { overflow-x: auto; -webkit-overflow-scrolling: touch; padding-right: 2.2rem; }
148	table.tab, table.grammar { border-collapse: collapse; font-size: .92rem; }
149	table.tab td { padding: 3px 12px 3px 0; vertical-align: top; white-space: nowrap; }
150	table.tab td.c { text-align: center; } table.tab td.r { text-align: right; }
151	table.tab tr.ruled td, table.tab tr.rule td { border-bottom: 1px solid var(--rule); }
152	.tw.gr { background: var(--surface); border: 1px solid var(--rule); border-radius: 6px; padding: 8px 2.2rem 8px 12px; }
153	.tw.gr .label { font-family: var(--mono); font-size: .72rem; color: var(--muted); margin: 0 0 .2rem; }
154	table.grammar td { padding: 1px 8px 1px 0; vertical-align: top; white-space: nowrap; }
155	.words { display: flex; flex-wrap: wrap; gap: 2px 18px; }
156	.fig { margin: 0 0 .9rem; } figcaption { font-size: .88rem; color: var(--muted); }
157	
158	/* the revival's callouts and the authors' draft notes */
159	aside.revision, aside.draft { border-left: 4px solid var(--rev-rule); background: var(--rev-bg); border-radius: 0 6px 6px 0; padding: 10px 14px; margin: 0 0 .9rem; }
160	aside.draft { border-left-color: var(--note-rule); background: var(--note-bg); font-size: .94rem; }
161	aside .label { font-family: var(--mono); font-size: .74rem; font-weight: 600; letter-spacing: .03em; text-transform: uppercase; margin: 0 0 .3rem; max-width: none; }
162	aside.revision .label { color: var(--rev-fg); } aside.draft .label { color: var(--muted); }
163	aside .label .see { text-transform: none; font-weight: 400; letter-spacing: 0; margin-left: .5em; }
164	aside > :last-child { margin-bottom: 0; }
165	.margin { color: var(--muted); font-size: .88em; }
166	.pending { font-size: .8em; color: var(--muted); font-family: var(--mono); white-space: nowrap; }
167	.gap, .unk { color: #a23; font-family: var(--mono); font-size: .85em; }
168	.thm { border-left: 3px solid var(--rule); padding-left: 12px; margin: 0 0 .9rem; }
169	.fnref a { text-decoration: none; padding: 0 .2em; }
170	section.fns { font-size: .9rem; }
171	
172	/* the contents page */
173	.contents h3 .num { display: block; }
174	ul.chapters { list-style: none; padding: 0; margin: 0 0 .6rem; border-top: 1px solid var(--rule); }
175	ul.chapters > li { margin: 0; padding: 7px 0; border-bottom: 1px solid var(--rule); max-width: none; }
176	ul.chapters > li.todo { color: var(--muted); }
177	ul.chapters > li.done > a { font-weight: 700; text-decoration: none; }
178	ul.chapters .num { display: inline-block; min-width: 2.2em; }
179	ul.chapters li.here > a::after { content: " · you are here"; font-weight: 400; font-size: .82rem; color: var(--muted); }
180	details.secs { font-size: .9rem; margin: .2rem 0 0 2.2em; }
181	details.secs summary { cursor: pointer; color: var(--muted); }
182	details.secs ol { list-style: none; padding: 0; margin: .3rem 0 .2rem; }
183	
184	/* where he left off, notes, export */
185	.resume, .chapter-notes, .warn { background: var(--surface); border: 1px solid var(--rule); border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0; padding: 10px 14px; font-size: .94rem; }
186	.resume p { margin: 0 0 .4rem; max-width: none; } .resume .where { font-weight: 700; }
187	.resume .excerpt { color: var(--muted); font-size: .88rem; }
188	.warn { border-left-color: var(--note-rule); background: var(--note-bg); }
189	.chapter-notes summary { cursor: pointer; font-weight: 700; }
190	.chapter-notes ol { margin: .5rem 0 0; }
191	.chapter-notes li { font-size: .9rem; }
192	.has-note { box-shadow: -3px 0 0 0 var(--bg), -6px 0 0 0 var(--note-rule); }
193	.note-card { background: var(--note-bg); border: 1px solid var(--note-rule); border-radius: 6px; padding: 8px 12px; margin: 0 0 .9rem; font-size: .94rem; max-width: 65ch; -webkit-user-select: none; user-select: none; }
194	.note-card .text { white-space: pre-wrap; margin: 0 0 .3rem; overflow-wrap: anywhere; }
195	.note-card .meta { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; font-family: var(--mono); font-size: .72rem; color: var(--muted); }
196	.note-card .meta::before { content: "Your note"; margin-right: auto; }
197	.note-card .where { font-size: .86rem; margin: 0 0 .3rem; } .note-card .excerpt { color: var(--muted); font-size: .86rem; margin: 0 0 .3rem; }
198	.note-edit { background: var(--note-bg); border: 1px solid var(--note-rule); border-radius: 6px; padding: 8px; margin: 0 0 .9rem; max-width: 65ch; }
199	textarea { display: block; width: 100%; font-family: var(--body); font-size: 16px; line-height: 1.45; color: var(--fg); background: var(--surface); border: 1px solid var(--rule); border-radius: 4px; padding: 8px; resize: vertical; }
200	#export-text, #import-text { font-family: var(--mono); font-size: .8rem; }
201	.actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: .5rem 0; max-width: none; }
202	button.act, label.act, a.act, .note-card .meta button { font-family: var(--mono); font-size: .8rem; font-weight: 600; color: var(--accent); background: var(--surface); border: 1px solid var(--rule); border-radius: 4px; padding: .45em .9em; cursor: pointer; min-height: 36px; }
203	.note-card .meta button { font-size: .72rem; padding: .3em .7em; min-height: 30px; }
204	button.act.primary, a.act.primary { background: var(--accent); color: var(--bg); border-color: var(--accent); }
205	button.act.danger, .note-card .meta button.danger { color: #b3261e; }
206	@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) button.act.danger, :root:not([data-theme="light"]) .note-card .meta button.danger { color: #f2a59f; } }
207	label.act.file { display: inline-flex; align-items: center; }
208	label.act.file input { position: absolute; width: 1px; height: 1px; opacity: 0; }
209	[role="status"] { font-size: .86rem; color: var(--muted); }
210	.flash { animation: flash 2.4s ease-out 1; }
211	@keyframes flash { from { background-color: var(--mark); } to { background-color: transparent; } }
212	.note-group h3 { margin-top: .6rem; }
213	.empty { color: var(--muted); }
214	
215	nav.pager { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; border-top: 1px solid var(--rule); padding-top: 14px; }
216	nav.pager a { display: block; text-decoration: none; font-weight: 700; padding: 8px 12px; border: 1px solid var(--rule); border-radius: 8px; background: var(--surface); }
217	nav.pager a span { display: block; font-family: var(--mono); font-size: .72rem; font-weight: 400; color: var(--muted); }
218	nav.pager a.next { text-align: right; }
219	p.ref { padding-left: 1.5em; text-indent: -1.5em; } p.ref .key { font-family: var(--mono); font-size: .86em; }
