128	  /* ---------- notes: the text form that is exported and imported ---------- */
129	  function chapterNum(n) { var m = /^([0-9]+|[A-Z])\./.exec(n.chapter || ''); return m ? m[1] : ''; }
130	  function sortKey(n) {
131	    var c = chapterNum(n), parts = [c === '' ? -1 : (/^\d+$/.test(c) ? +c : 1000 + c.charCodeAt(0))];
132	    (n.secNum || '').split('.').slice(1).forEach(function (p) { parts.push(+p || 0); });
133	    return parts;
134	  }
135	  function sorted(list) {
136	    return list.slice().sort(function (a, b) {
137	      var x = sortKey(a), y = sortKey(b);
138	      for (var i = 0; i < Math.max(x.length, y.length); i++) {
139	        var d = (x[i] || 0) - (y[i] || 0);
140	        if (d) return d;
141	      }
142	      return (a.created || '') < (b.created || '') ? -1 : 1;
143	    });
144	  }
145	  function linkOf(n) { return BASE + n.page + '.html#' + n.anchor; }
146	  function sectionLine(n) {
147	    if (n.secNum && n.secNum.indexOf('.') < 0) return "(the chapter's opening)";
148	    return ((n.secNum ? n.secNum + ' ' : '') + (n.secTitle || '')).trim() || "(the chapter's opening)";
149	  }
150	  function exportText(list) {
151	    list = sorted(list);
