153	               'Reader: ' + BASE, 'Notes: ' + list.length, ''];
154	    list.forEach(function (n, i) {
155	      out.push('=== Note ' + (i + 1) + ' of ' + list.length + ' ===');
156	      out.push('Chapter: ' + (n.chapter || n.page));
157	      out.push('Section: ' + sectionLine(n));
158	      out.push('Link: ' + linkOf(n));
159	      out.push('Passage (' + (n.kind || 'paragraph') + '): ' + (n.excerpt || ''));
160	      out.push('Written: ' + (n.updated || n.created || ''));
161	      out.push('Id: ' + n.id);
162	      out.push('Note:');
163	      String(n.text).split('\n').forEach(function (l) { out.push('  ' + l); });
164	      out.push('');
165	    });
166	    return out.join('\n');
167	  }
168	  function parseExport(text) {
169	    var chunks = text.replace(/\r\n?/g, '\n').split(/^=== Note \d+ of \d+ ===[ \t]*$/m).slice(1), out = [];
170	    chunks.forEach(function (chunk) {
171	      var lines = chunk.replace(/^\n/, '').split('\n'), f = {}, i = 0, m;
172	      for (; i < lines.length; i++) {
173	        if (/^Note:\s*$/.test(lines[i])) { i++; break; }
174	        m = /^([A-Za-z]+)(?: \(([^)]*)\))?: ?(.*)$/.exec(lines[i]);
175	        if (m) { f[m[1]] = m[3]; if (m[2]) f[m[1] + 'Kind'] = m[2]; }
176	      }
177	      var bodyLines = lines.slice(i).map(function (l) { return l.replace(/^ {1,2}/, ''); });
178	      while (bodyLines.length && !bodyLines[bodyLines.length - 1].trim()) bodyLines.pop();
179	      var link = /([^\/#?]+)\.html#(.+)$/.exec(f.Link || '');
180	      if (!link || !bodyLines.length) return;
181	      var sec = /^((?:\d+|[A-Z])(?:\.\d+)+)\s+(.*)$/.exec(f.Section || '');
182	      var chap = /^((?:\d+|[A-Z]))\.\s+(.*)$/.exec(f.Chapter || '');
183	      out.push({
184	        id: f.Id || '', page: link[1], anchor: link[2].trim(), chapter: f.Chapter || link[1],
185	        secNum: sec ? sec[1] : (chap ? chap[1] : ''), secTitle: sec ? sec[2] : (chap ? chap[2] : ''),
186	        kind: f.PassageKind || 'paragraph', excerpt: f.Passage || '', text: bodyLines.join('\n'),
187	        created: f.Written || new Date().toISOString(), updated: f.Written || new Date().toISOString()
188	      });
189	    });
190	    return out;
191	  }
192	  function newId() { return 'n' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
193	  function mergeNotes(incoming) {
194	    var list = notes(), added = 0, updated = 0, same = 0;
195	    incoming.forEach(function (n) {
196	      var old = null;
197	      list.forEach(function (o) {
198	        if ((n.id && o.id === n.id) || (o.page === n.page && o.anchor === n.anchor && o.text === n.text)) old = o;
199	      });
200	      if (!old) { if (!n.id) n.id = newId(); list.push(n); added++; return; }
201	      if (old.text === n.text) { same++; return; }
202	      if ((n.updated || '') > (old.updated || '')) { old.text = n.text; old.updated = n.updated; updated++; }
203	      else same++;
204	    });
205	    saveNotes(list);
206	    return { added: added, updated: updated, same: same };
207	  }
